Review this Python function for a memory leak or inefficiency:
    def process_data(large_list):
        result = []
        for item in large_list:
            if item not in result:
                result.append(item)
        return result
    Explain why it performs poorly on large inputs and provide an optimized O(n) version.

Debug the following Go code block. Identify the race condition or issue, explain why it happens, and provide the corrected version:
    func main() {
        var wg sync.WaitGroup
        count := 0
        for i := 0; i < 1000; i++ {
            wg.Add(1)
            go func() {
                count++
                wg.Done()
            }()
        }
        wg.Wait()
        fmt.Println(count)
    }

